let roles = body.roles;
if (!roles) roles = [];
else if (!Array.isArray(roles)) roles = [roles];
roles = roles.map((r) => String(r).trim()).filter((r) => VALID_ROLES.has(r));
if (roles.length === 0) roles = ['Contract Signer'];
const _orgRest = baseUrl.replace(/^[a-z]+:\/\//i, '');
const organization = 'did:web:' + encodeURIComponent(_orgRest.split('/')[0]);

