    '.footer-links{margin-top:1.75rem;font-size:.75rem;color:#94a3b8;}\n' +
    '.footer-links a{color:#6366f1;text-decoration:none;margin:0 .4rem;}\n' +
    '.footer-links a:hover{text-decoration:underline;}\n' +
    '</style>\n' +
    '</head>\n' +
    '<body>\n' +
