    '<div class="chips">' + roleChips + '</div>\n' +
    '<div class="qr-frame"><img src="' + qrDataUrl + '" alt="Credential offer QR code"></div>\n' +
    '<ol class="steps">\n' +
    '<li>Open the Paradym Wallet app</li>\n' +
