  msg.statusCode = 200;
  msg.headers = { 'content-type': 'text/html' };
  msg.payload = html;
  node.send(msg);
});
return null;

const id = msg.req.params.id;
const offers = global.get('offers') || {};
const offer = offers[id];

if (!offer) {
  msg.statusCode = 404;
  msg.headers = { 'content-type': 'application/json' };
  msg.payload = { error: 'not_found', error_description: 'unknown offer id' };
  return msg;
}

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = offer;
return msg;

const body = msg.payload || {};
const preAuthCodes = global.get('preAuthCodes') || {};
const code = body['pre-authorized_code'];
const entry = code ? preAuthCodes[code] : null;

const valid = body.grant_type === 'urn:ietf:params:oauth:grant-type:pre-authorized_code' &&
  entry && !entry.used && entry.exp > Date.now();

if (!valid) {
  msg.statusCode = 400;
  msg.headers = { 'content-type': 'application/json' };
  msg.payload = { error: 'invalid_grant' };
  return msg;
}

entry.used = true;
global.set('preAuthCodes', preAuthCodes);

const accessToken = crypto.randomBytes(24).toString('base64url');
const cNonce = crypto.randomBytes(16).toString('base64url');

const accessTokens = global.get('accessTokens') || {};
accessTokens[accessToken] = {
  claims: entry.claims,
  cNonce,
  exp: Date.now() + 300000
};
global.set('accessTokens', accessTokens);

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
  access_token: accessToken,
  token_type: 'bearer',
  expires_in: 300,
  c_nonce: cNonce,
  c_nonce_expires_in: 300
};
return msg;

// This credential and the status list it points at are the same issuer's
// statement, signed with the same key and identified the same way: the leaf
// minted for the URL this request arrived through, chained to this issuer's
// root, which the verifier already anchors because the status list made it
// anchor it (ADR-34). The trust entry naming this issuer therefore declares
// mechanism x5c -- DCS refuses an x5c-bearing credential from an issuer
// configured to publish its key any other way, and refuses one WITHOUT a chain
// from an issuer configured as x5c (backend/internal/auth/oid4vp/sdjwt/
// keys.go, ResolveIssuerVerificationKey). `kid` stays alongside for a wallet
// that resolves did:web instead; it is not what DCS reads.
const CREDENTIAL_JWT_TYP = 'dc+sd-jwt';
const CREDENTIAL_VCT = 'urn:dcs:poa:v1';

// This container's clock can be far off real-world time (see the PKI tab's
// faketime comment for why). Stamping iat/exp from container Date.now()
// can read as "not yet valid" to a verifier on a real device. Anchor both
// to fixed, safely-past/future timestamps instead -- same 2020 anchor the
// PKI tab backdates certs to.
const SAFE_IAT_FALLBACK = Math.floor(Date.parse('2020-01-01T00:00:00Z') / 1000);
// exp stays a fixed, generously-future anchor regardless of where iat came
// from -- so even the fallback path (real-world time fetch failed) never
// issues an already-expired credential.
const SAFE_EXP = Math.floor(Date.parse('2045-01-01T00:00:00Z') / 1000);

// Some wallets bind the proof key via an embedded `jwk` header (what our
// own test client does); others reference it via a `kid` that is itself a
// did:jwk DID URL (did:jwk is just base64url(JSON(jwk)), no resolver
// needed -- decode it locally). Accept either.
function didJwkToJwk(didUrl) {
  if (typeof didUrl !== 'string') return null;
  const did = didUrl.split('#')[0];
  if (!did.startsWith('did:jwk:')) return null;
  try {
    const decoded = JSON.parse(Buffer.from(did.slice('did:jwk:'.length), 'base64url').toString('utf8'));
    if (!decoded.kty || !decoded.x) return null;
    return { kty: decoded.kty, crv: decoded.crv, x: decoded.x, y: decoded.y };
  } catch (e) {
    return null;
  }
}

(async () => {
  try {
    const baseUrl = global.get('getBaseUrl')(msg);

    const authHeader = (msg.req.headers.authorization || '');
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
    const accessTokens = global.get('accessTokens') || {};
    const tokenEntry = token ? accessTokens[token] : null;

    if (!tokenEntry || tokenEntry.exp < Date.now()) {
      msg.statusCode = 401;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_token' };
      node.send(msg);
      return;
    }

    const body = msg.payload || {};
    node.warn('[vci /credential] incoming body: ' + JSON.stringify(body).slice(0, 4000));

    // Older OpenID4VCI drafts (and our own test client) send a singular
    // `proof: {proof_type, jwt}`. Newer drafts (what Paradym/Credo actually
    // send) use a plural `proofs: {jwt: ["<jwt>", ...]}` to support batch
    // issuance -- accept either, taking the first proof from the array.
    let proofJwt = null;
    if (body.proof && body.proof.jwt) {
      proofJwt = body.proof.jwt;
    } else if (body.proofs && Array.isArray(body.proofs.jwt) && body.proofs.jwt.length > 0) {
      proofJwt = body.proofs.jwt[0];
    }
    const usedPluralProofs = !!(body.proofs && Array.isArray(body.proofs.jwt));

    if (!proofJwt) {
      node.warn('[vci /credential] reject: no proof.jwt or proofs.jwt[] in body');
      msg.statusCode = 400;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_or_missing_proof', error_description: 'no proof.jwt or proofs.jwt[] in request body' };
      node.send(msg);
      return;
    }

    const parts = proofJwt.split('.');
    if (parts.length !== 3) {
      node.warn('[vci /credential] reject: proof.jwt has ' + parts.length + ' dot-separated parts, expected 3');
      msg.statusCode = 400;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_or_missing_proof', error_description: 'proof.jwt is not a 3-part compact JWT' };
      node.send(msg);
      return;
    }

    let header, payload;
    try {
      header = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
      payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    } catch (e) {
      node.warn('[vci /credential] reject: could not JSON-parse proof header/payload -- ' + e.message);
      msg.statusCode = 400;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_or_missing_proof', error_description: 'proof header/payload not valid JSON' };
      node.send(msg);
      return;
    }
    node.warn('[vci /credential] proof header: ' + JSON.stringify(header));
    node.warn('[vci /credential] proof payload: ' + JSON.stringify(payload));

    let holderJwk = null;
    if (header.jwk) {
      holderJwk = { kty: header.jwk.kty, crv: header.jwk.crv, x: header.jwk.x, y: header.jwk.y };
    } else if (header.kid) {
      holderJwk = didJwkToJwk(header.kid);
      if (!holderJwk) node.warn('[vci /credential] header.kid present but not a decodable did:jwk: ' + header.kid);
    }

    if (header.alg !== 'ES256' || !holderJwk) {
      node.warn('[vci /credential] reject: alg=' + header.alg + ' hasJwk=' + !!header.jwk + ' kid=' + header.kid + ' resolvedHolderJwk=' + !!holderJwk);
      msg.statusCode = 400;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_or_missing_proof', error_description: 'proof header must have alg=ES256 and either an embedded jwk or a did:jwk kid' };
      node.send(msg);
      return;
    }

    if (payload.nonce !== tokenEntry.cNonce) {
      const freshNonce = crypto.randomBytes(16).toString('base64url');
      tokenEntry.cNonce = freshNonce;
      global.set('accessTokens', accessTokens);
      node.warn('[vci /credential] reject: nonce mismatch, rotated c_nonce');
      msg.statusCode = 400;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_proof', c_nonce: freshNonce, c_nonce_expires_in: 300 };
      node.send(msg);
      return;
    }

    if (payload.aud !== baseUrl) {
      node.warn('[vci /credential] proof aud mismatch: got ' + payload.aud + ' expected ' + baseUrl);
    }

    const signingInput = parts[0] + '.' + parts[1];
    let sigOk = false;
    try {
      sigOk = crypto.verify(
        'sha256',
        Buffer.from(signingInput),
        { key: holderJwk, format: 'jwk', dsaEncoding: 'ieee-p1363' },
        Buffer.from(parts[2], 'base64url')
      );
    } catch (e) {
      node.warn('[vci /credential] signature verify threw: ' + e.message);
      sigOk = false;
    }
    if (!sigOk) {
      node.warn('[vci /credential] reject: proof signature did not verify against holder jwk');
      msg.statusCode = 400;
      msg.headers = { 'content-type': 'application/json' };
      msg.payload = { error: 'invalid_proof', error_description: 'proof signature did not verify' };
      node.send(msg);
      return;
    }

    // did:jwk is just base64url(JSON(jwk)) -- self-contained, no resolver
    // needed. Pin member order so the same key always yields the same DID.
    const holderDidJwk = 'did:jwk:' + Buffer.from(JSON.stringify(holderJwk)).toString('base64url');

    // Registry is disk-backed (boot tab) -- reconcile the in-memory counter
    // with it after a restart so indices never get reused across a redeploy.
    const registry = global.get('loadRegistry')();
    let idx = global.get('statusListNextIdx');
    if (idx === undefined || idx === null || idx < registry.length) idx = registry.length;
    global.set('statusListNextIdx', idx + 1);

    // Mints the leaf if this base URL has never been served before, so a
    // credential is never signed by a certificate that names nobody -- the
    // boot-time certificate cannot name a URL the pod learns from a request.
    const pki = global.get('ensureIssuerCertFor')(baseUrl);

    // The DID is the issuer's identity in `iss`, and the leaf above carries it
    // as a URI SAN -- which is what lets a verifier accept the chain as this
    // issuer's rather than merely as one some anchor vouched for. Paradym
    // resolves the same DID live over HTTPS instead (see the PKI tab's
    // /.well-known/did.json); both read the same key.
    // Path-segmented when deployed under a prefix, so the DID resolves to
    // <authority>/<segments>/did.json. Must match the PKI tab's did.json.
    const _rest = baseUrl.replace(/^[a-z]+:\/\//i, '');
    const _authority = _rest.split('/')[0];
    const _segs = _rest.split('/').slice(1).filter(Boolean);
    const issuerDid = 'did:web:' + encodeURIComponent(_authority) + (_segs.length ? ':' + _segs.join(':') : '');
    const issuerKeyId = issuerDid + '#key-1';

    const signer = async (data) => {
      const sig = crypto.sign(
        'sha256',
        Buffer.from(data),
        { key: crypto.createPrivateKey(pki.issuerKeyPem), dsaEncoding: 'ieee-p1363' }
      );
      return sig.toString('base64url');
    };

    const sdjwt = new sdjwtVc.SDJwtVcInstance({
      signer,
      signAlg: 'ES256',
      hasher: sdjwtCrypto.digest,
      hashAlg: 'sha-256',
      saltGenerator: sdjwtCrypto.generateSalt
    });

    const realNow = await global.get('getRealWorldNowSeconds')();
    const iat = realNow || SAFE_IAT_FALLBACK;

    const claims = {
      iss: baseUrl,
      sub: holderDidJwk,
      cnf: { jwk: holderJwk },
      vct: CREDENTIAL_VCT,
      iat,
      exp: SAFE_EXP,
      status: { status_list: { idx, uri: baseUrl + '/status-list/1' } },
      organization: tokenEntry.claims.organization,
      roles: tokenEntry.claims.roles
    };
    // organization + roles are selectively disclosed per DCS's claims.go
    // (RolesFromClaims / OrganizationFromClaims read them via the standard
    // decode+getClaims merge, so this is transparent either way -- but do it
    // properly since the library already supports it).
    const disclosureFrame = { _sd: ['organization', 'roles'] };
    const jwtHeader = {
      alg: 'ES256',
      typ: CREDENTIAL_JWT_TYP,
      x5c: [pki.issuerCertDerB64, pki.rootCaCertDerB64]
    };

    const encodedSdjwt = await sdjwt.issue(claims, disclosureFrame, { header: jwtHeader });

    registry.push({
      idx,
      issuedAt: new Date().toISOString(),
      claims: tokenEntry.claims,
      holderDid: holderDidJwk,
      revoked: false,
      revokedAt: null
    });
    global.get('saveRegistry')(registry);

    // Respond with both the older singular `credential` field and the
    // newer plural `credentials` array (used when the request itself used
    // plural `proofs`) -- an extra unused field is harmless, but a missing
    // one that the client actually reads for is not.
    msg.statusCode = 200;
    msg.headers = { 'content-type': 'application/json' };
    msg.payload = {
      format: 'dc+sd-jwt',
      credential: encodedSdjwt,
      credentials: [{ credential: encodedSdjwt }]
    };
    node.log('[vci /credential] issued credential idx=' + idx + ' usedPluralProofs=' + usedPluralProofs);
    node.send(msg);
  } catch (err) {
    node.warn('[vci /credential] unexpected error: ' + (err && err.stack || err));
    msg.statusCode = 500;
    msg.headers = { 'content-type': 'application/json' };
    msg.payload = { error: 'server_error', error_description: String(err) };
    node.send(msg);
  }
})();
return null;
